import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div"> {}

<const/{ class: className, content, ...rest }=input/>

<div data-slot="bubble-group" class=cn("mu-bubble-group flex min-w-0 flex-col", className) ...rest>
  <${content}/>
</div>

import { bubbleReactionsVariants, type BubbleReactionsVariants } from "./variants.ts";
import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div">, BubbleReactionsVariants {
  align?: "start" | "end";
  side?: "top" | "bottom";
}

<const/{ side = "bottom", align = "end", class: className, content, ...rest }=input/>

<div
  data-slot="bubble-reactions"
  data-align=align
  data-side=side
  class=cn(bubbleReactionsVariants({ side, align }), className)
  ...rest
>
  <${content}/>
</div>

import { bubbleVariants, type BubbleVariants } from "./variants.ts";
import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div">, BubbleVariants {
  align?: "start" | "end";
}

<const/{ variant = "default", align = "start", class: className, content, ...rest }=input/>

<div
  data-slot="bubble"
  data-variant=variant
  data-align=align
  class=cn(bubbleVariants({ variant }), className)
  ...rest
>
  <${content}/>
</div>

import { cva, type VariantProps } from "class-variance-authority";

export const bubbleVariants = cva(
  "mu-bubble group/bubble relative flex w-fit min-w-0 flex-col",
  {
    variants: {
      variant: {
        default: "mu-bubble-variant-default",
        secondary: "mu-bubble-variant-secondary",
        muted: "mu-bubble-variant-muted",
        tinted: "mu-bubble-variant-tinted",
        outline: "mu-bubble-variant-outline",
        ghost: "mu-bubble-variant-ghost",
        destructive: "mu-bubble-variant-destructive",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

export type BubbleVariants = VariantProps<typeof bubbleVariants>;

export const bubbleReactionsVariants = cva(
  "mu-bubble-reactions absolute z-10 flex w-fit items-center justify-center",
  {
    variants: {
      side: {
        top: "mu-bubble-reactions-side-top",
        bottom: "mu-bubble-reactions-side-bottom",
      },
      align: {
        start: "mu-bubble-reactions-align-start",
        end: "mu-bubble-reactions-align-end",
      },
    },
    defaultVariants: {
      side: "bottom",
      align: "end",
    },
  },
);

export type BubbleReactionsVariants = VariantProps<typeof bubbleReactionsVariants>;
